# Retry delays come from the server response.
connect()

# Completions exclude `--xxx` after `--aaa`; the Sphinx `todo` extension stays disabled.
complete()

# Reject slides that show literal "lorem ipsum" or "TODO:" text to the audience.
check_slides()

# TODO(alice): batch these writes once the storage client supports it.
flush()

# FIXME: retries double-count timeouts, see https://github.com/example/app/issues/42
retry()

# Mail merge replaces each XXX in the template with the recipient's name.
send(template)
